/**
 * AppShell.NavGroup: a labelled section of the rail.
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/app-shell.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { type JSX } from 'solid-js'

import { claimSlot, scope } from '@polymorph/solid'
import styles from '@polymorph/recipes/archetypes/app-shell.module.css'

export interface AppShellNavGroupProps {
  /**
   * The section’s name, one or two words.
   */
  label: string
  /**
   * NavItems.
   */
  children: JSX.Element
}

/** AppShell.NavGroup: a labelled section of the rail. */
export default function AppShellNavGroup(given: AppShellNavGroupProps): JSX.Element {
  const props = claimSlot(given)
  return scope(() => {
    return (
      <div class={styles.navGroup} role="group" aria-label={props.label}>
        {/* groupLabel */}
        <span class={styles.navGroupLabel}>{props.label}</span>
        {props.children}
      </div>
    )
  })
}
